/// <summary>
/// This class defines the business event for inventory on-hand storage operations.
/// </summary>
[BusinessEvents(classStr(METInventOnhandStorageBusinessContract), '@MET:InventOnhandReportBE', '@MET:InventOnhandReportBEDesc', ModuleAxapta::Inventory)]
final class METInventOnhandStorageBusinessEvent extends BusinessEventsBase
{
    private CreatedTransactionId inventoryOnhandReportId;
    private ExecutionNameInventOnhand inventoryOnhandReportName;
    private ExecutionTimeInventOnhand inventoryOnhandReportExecutionTime;

}

