/// <summary>
/// This is the constructor for the METInventOnhandStorageBusinessEvent class.
/// </summary>
private void new()
{
}

/// <summary>
/// This method creates a new instance of the METInventOnhandStorageBusinessEvent class using the provided parameters.
/// </summary>
/// <param name = "_inventoryOnhandReportId">CreatedTransactionId</param>
/// <param name = "_inventoryOnhandReportName">ExecutionNameInventOnhand</param>
/// <param name = "_inventoryOnhandReportExecutionTime">ExecutionTimeInventOnhand</param>
/// <returns>METInventOnhandStorageBusinessEvent</returns>
public static METInventOnhandStorageBusinessEvent newFromParameters(CreatedTransactionId _inventoryOnhandReportId, ExecutionNameInventOnhand _inventoryOnhandReportName, ExecutionTimeInventOnhand _inventoryOnhandReportExecutionTime)
{
    METInventOnhandStorageBusinessEvent event = new METInventOnhandStorageBusinessEvent();
    event.inventoryOnhandReportId = _inventoryOnhandReportId;
    event.inventoryOnhandReportName = _inventoryOnhandReportName;
    event.inventoryOnhandReportExecutionTime = _inventoryOnhandReportExecutionTime;

    return event;
}

/// <summary>
/// This method builds and returns the business event contract.
/// </summary>
/// <returns>BusinessEventsContract</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    METInventOnhandStorageBusinessContract contract = METInventOnhandStorageBusinessContract::newFromParameters(inventoryOnhandReportId, inventoryOnhandReportName, inventoryOnhandReportExecutionTime);

    return contract;
}
